import {HeadJson} from 'shared';
import {DocRaw} from '../../types/doc-raw';
import {validateTaxRates} from './validate-tax-rates';

// generated by claude. Comments added by me.

// mock any doc raw. Only necessary fields are set (type, lineNr) but others can be given to it.
const raw = (lineNr: number, type: string, extra: Partial<DocRaw> = {}): DocRaw =>
    ({lineNr, type, ...extra}) as DocRaw;

// mock an entire rawDocument structure. Only needed fields are used.
const headRaw = raw(1, 'HEAD', {
    alcs: [raw(4, 'ALC')],
    pos: [raw(2, 'POS', {alcs: [raw(3, 'ALC')]})],
});

// head json, only the tax rates are read
const headJson = (ohtmws: string | undefined, opomws: string | undefined, headAlc: string | undefined, posAlc: string | undefined): HeadJson =>
    ({
        OHTMWS: ohtmws,
        HEAD_ALC: [{OZAMWS: headAlc}],
        POS: [{OPOMWS: opomws, POS_ALC: [{OZAMWS: posAlc}]}],
    }) as HeadJson;

describe('validateTaxRates', () => {
    it('does nothing when a global rate is set', () => {
        expect(() => validateTaxRates(headRaw, headJson('19,00', undefined, undefined, undefined))).not.toThrow();
    });

    it('accepts own rates on all levels with global rate 0', () => {
        expect(() => validateTaxRates(headRaw, headJson('0,00', '19,00', '19,00', '7,00'))).not.toThrow();
    });

    it('accepts own rates on all levels with global rate undefined (treated as 0)', () => {
        expect(() => validateTaxRates(headRaw, headJson(undefined, '19,00', '19,00', '19,00'))).not.toThrow();
    });

    it('rejects a position without rate if no global rate is set and reports its line', () => {
        expect(() => validateTaxRates(headRaw, headJson('0,00', undefined, '19,00', '19,00'))).toThrow('Zeile 2 (POS)');
    });

    it('rejects a position rate of 0', () => {
        expect(() => validateTaxRates(headRaw, headJson('0,00', '0,00', '19,00', '19,00'))).toThrow('Zeile 2 (POS)');
    });

    it('rejects a head ALC without rate if no global rate is set and reports its line', () => {
        expect(() => validateTaxRates(headRaw, headJson('0,00', '19,00', undefined, '19,00'))).toThrow('Zeile 4 (ALC)');
    });

    it('rejects a head ALC rate of 0', () => {
        expect(() => validateTaxRates(headRaw, headJson('0,00', '19,00', '0,00', '19,00'))).toThrow('Zeile 4 (ALC)');
    });

    it('rejects a position ALC without rate and reports its line', () => {
        expect(() => validateTaxRates(headRaw, headJson('0,00', '19,00', '19,00', undefined))).toThrow('Zeile 3 (ALC)');
    });

    it('rejects a pos ALC with rate 0 and reports its line', () => {
        expect(() => validateTaxRates(headRaw, headJson('0,00', '19,00', '19,00', '0,00'))).toThrow('Zeile 3 (ALC)');
    });
});